# --- Логика выдачи без повторов с зацикливанием (отдельно для новых и старых вопросов) ---
new_pool: list[int] = []
old_pool: list[int] = []
_last_catchup_date = None


def _refill_pool(pool_name: str):
    global new_pool, old_pool
    if pool_name == "new":
        new_pool = list(range(len(NEW_QUESTIONS)))
        random.shuffle(new_pool)
        logger.info("Пул НОВЫХ вопросов перемешан заново (%d шт.)", len(new_pool))
    else:
        old_pool = list(range(len(OLD_QUESTIONS)))
        random.shuffle(old_pool)
        logger.info("Пул СТАРЫХ вопросов перемешан заново (%d шт.)", len(old_pool))


def get_daily_questions() -> list[dict]:
    global new_pool, old_pool
    selected = []

    for _ in range(NEW_PER_DAY):
        if not new_pool:
            _refill_pool("new")
        selected.append(NEW_QUESTIONS[new_pool.pop()])

    for _ in range(OLD_PER_DAY):
        if not old_pool:
            _refill_pool("old")
        selected.append(OLD_QUESTIONS[old_pool.pop()])

    random.shuffle(selected)  # перемешиваем порядок, чтобы старые/новые не шли блоками
    return selected


async def send_daily_quiz(context: ContextTypes.DEFAULT_TYPE):
    try:
        questions = get_daily_questions()
        await context.bot.send_message(
            chat_id=GROUP_ID,
            text="На одном МБО не уедешь !  Полный газ 👇",
        )
        for q in questions:
            # Telegram: вариант ответа ≤ 100 симв., объяснение в poll ≤ 200 симв.
            await context.bot.send_poll(
                chat_id=GROUP_ID,
                question=q["question"][:300],
                options=[opt[:100] for opt in q["options"]],
                type="quiz",
                correct_option_id=q["correct"],
                is_anonymous=True,
                explanation=q["explanation"][:200],
            )
            await asyncio.sleep(1)  # чтобы не словить flood limit
        logger.info("Квиз из %d вопросов отправлен в группу %s", len(questions), GROUP_ID)
    except Exception as e:
        logger.error("Ошибка при отправке квиза: %s", e, exc_info=True)


async def _catchup_quiz(context: ContextTypes.DEFAULT_TYPE):
    """Разовый дослыл пропущенного квиза, но не чаще одного раза в день."""
    global _last_catchup_date
    today = context.job.data
    if _last_catchup_date == today:
        logger.info("Дослыл уже был сегодня — пропускаю")
        return
    _last_catchup_date = today
    logger.info("Дослыл пропущенного квиза за %s", today)
    await send_daily_quiz(context)


async def start(update: Update, context: ContextTypes.DEFAULT_TYPE):
    await update.message.reply_text(
        "✅ MacroQuiz работает! Каждый день в 10:00 МСК — 10 вопросов-викторин по макроэкономике.\n\n"
        "Команды:\n/quiznow — прислать вопросы прямо сейчас"
    )


async def quiz_now(update: Update, context: ContextTypes.DEFAULT_TYPE):
    await send_daily_quiz(context)


class HealthHandler(BaseHTTPRequestHandler):
    def do_GET(self):
        self.send_response(200)
        self.end_headers()
        self.wfile.write(b"OK")

    def log_message(self, format, *args):
        pass


def run_health_server():
    port = int(os.environ.get("PORT", 5000))
    server = HTTPServer(("0.0.0.0", port), HealthHandler)
    logger.info("Health-сервер запущен на порту %s", port)
    server.serve_forever()


def main():
    threading.Thread(target=run_health_server, daemon=True).start()

    app = Application.builder().token(BOT_TOKEN).build()

    if app.job_queue is None:
        logger.error("JobQueue не установлен! Добавь 'python-telegram-bot[job-queue]' в requirements.txt")
        raise SystemExit(1)

    app.add_handler(CommandHandler("start", start))
    app.add_handler(CommandHandler("quiznow", quiz_now))

    # Ежедневная рассылка в 10:00 МСК
    app.job_queue.run_daily(
        send_daily_quiz,
        time=time(hour=QUIZ_HOUR, minute=QUIZ_MINUTE, tzinfo=MOSCOW_TZ),
    )

    # Если бот запустился ПОСЛЕ 10:00 МСК и сегодня квиз ещё не уходил — дослать через 5 сек
    now = datetime.now(MOSCOW_TZ)
    today_quiz_time = now.replace(hour=QUIZ_HOUR, minute=QUIZ_MINUTE, second=0, microsecond=0)
    catchup_window = timedelta(minutes=15)
    if today_quiz_time <= now <= today_quiz_time + catchup_window:
        app.job_queue.run_once(_catchup_quiz, when=5, data=now.date())

    logger.info(
        "MacroQuiz запущен ✅ (%d новых + %d старых вопросов в базе, квиз в %02d:%02d МСК)",
        len(NEW_QUESTIONS), len(OLD_QUESTIONS), QUIZ_HOUR, QUIZ_MINUTE,
    )
    app.run_polling(drop_pending_updates=True)


if __name__ == "__main__":
    main()
